// Rarity cut-offs on the summed score (20,000-seed simulation, empty params):
// Common 39.9% / Uncommon 37.7% / Rare 17.6% / Legendary 4.2% / Mythic 0.6%.
const (
	scoreMythic    = 9
	scoreLegendary = 7
	scoreRare      = 5
	scoreUncommon  = 3
)

// TraitSet is the decoded properties of a seed. The SVG builder and the
// trait list both read it, so picture and metadata cannot disagree.
type TraitSet struct {
	Era          string
	Section      string
	Folding      string
	Faults       string
	Intrusion    string
	Bedding      string
	Unconformity string
	Fossil       string
	Score        int
	Rarity       string
}

type derived struct {
	era, section, folding, faults, intrusion, bedding, unconf, fossil int
}

// derive draws every trait from seed+"|traits" in the prototype's order,
// then applies the params. Forced traits are still drawn, so fixing one
// trait never shifts the others.
func derive(seed string, p params) derived {
	r := newRNG(seed + "|traits")
	d := derived{
		era:       pick(r, eras),
		section:   pick(r, sections),
		folding:   pick(r, foldings),
		faults:    pick(r, faultsT),
		intrusion: pick(r, intrusions),
		bedding:   pick(r, beddings),
		unconf:    pick(r, unconfs),
		fossil:    pick(r, fossils),
	}
	if p.era >= 0 {
		d.era = p.era
	}
	if p.section >= 0 {
		d.section = p.section
	}
	if p.bedding >= 0 {
		d.bedding = p.bedding
	}
	if p.folding >= 0 {
		d.folding = p.folding
	}
	return d
}

func (d derived) traitSet() TraitSet {
	t := TraitSet{
		Era:          eras[d.era].name,
		Section:      sections[d.section].name,
		Folding:      foldings[d.folding].name,
		Faults:       faultsT[d.faults].name,
		Intrusion:    intrusions[d.intrusion].name,
		Bedding:      beddings[d.bedding].name,
		Unconformity: unconfs[d.unconf].name,
		Fossil:       fossils[d.fossil].name,
	}
	score := eras[d.era].score + sections[d.section].score + foldings[d.folding].score +
		faultsT[d.faults].score + intrusions[d.intrusion].score + beddings[d.bedding].score +
		unconfs[d.unconf].score + fossils[d.fossil].score
	t.Score = score
	switch {
	case score >= scoreMythic:
		t.Rarity = "Mythic"
	case score >= scoreLegendary:
		t.Rarity = "Legendary"
	case score >= scoreRare:
		t.Rarity = "Rare"
	case score >= scoreUncommon:
		t.Rarity = "Uncommon"
	default:
		t.Rarity = "Common"
	}
	return t
}

// TraitsOf returns the traits of a seed under default params.
func TraitsOf(seed string) TraitSet { return derive(seed, params{-1, -1, -1, -1}).traitSet() }

// TraitsWith returns the traits of a seed under params; it panics on
// params ValidateParams rejects.
func TraitsWith(seed, ps string) TraitSet { return derive(seed, mustParams(ps)).traitSet() }

// TraitString is "Type=Value;..." in TraitTypes order (golden vectors).
func TraitString(seed, ps string) string {
	t := TraitsWith(seed, ps)
	vals := []string{t.Era, t.Section, t.Folding, t.Faults, t.Intrusion, t.Bedding, t.Unconformity, t.Fossil, t.Rarity}
	var b strings.Builder
	for i, v := range vals {
		if i > 0 {
			b.WriteString(";")
		}
		b.WriteString(traitTypes[i])
		b.WriteString("=")
		b.WriteString(v)
	}
	return b.String()
}

// ---------------------------------------------------------------------------
// Integer trigonometry: a quarter-wave table, 256 steps per turn, x1024.
// ---------------------------------------------------------------------------

var quarter = []int{0, 25, 50, 75, 100, 125, 150, 175, 200, 224, 249, 273, 297, 321, 345, 369, 392, 415, 438, 460,
	483, 505, 526, 548, 569, 590, 610, 630, 650, 669, 688, 706, 724, 742, 759, 775, 792, 807, 822,
	837, 851, 865, 878, 891, 903, 915, 926, 936, 946, 955, 964, 972, 980, 987, 993, 999, 1004, 1009,
	1013, 1016, 1019, 1021, 1023, 1024, 1024}

func isin(a int) int {
	a %= 256 // Euclidean, as the prototype's Python %
	if a < 0 {
		a += 256
	}
	switch {
	case a < 64:
		return quarter[a]
	case a < 128:
		return quarter[128-a]
	case a < 192:
		return -quarter[a-128]
	}
	return -quarter[256-a]
}

func icos(a int) int { return isin(a + 64) }

// ---------------------------------------------------------------------------
// Drawing
// ---------------------------------------------------------------------------

const (
	canvas = 1000
	step   = 25
	npts   = canvas/step + 1 // 41 sample columns, x = 0, 25, ... 1000
)

const hexDigits = "0123456789abcdef"

func hexVal(c byte) int {
	if c >= 'a' {
		return int(c-'a') + 10
	}
	return int(c - '0')
}

// shade adds d to each channel of "#rrggbb", clamped to 0..255.
func shade(c string, d int) string {
	out := []byte{'#', 0, 0, 0, 0, 0, 0}
	for i := 0; i < 3; i++ {
		v := hexVal(c[1+2*i])*16 + hexVal(c[2+2*i]) + d
		if v < 0 {
			v = 0
		}
		if v > 255 {
			v = 255
		}
		out[1+2*i] = hexDigits[v/16]
		out[2+2*i] = hexDigits[v%16]
	}
	return string(out)
}

type art struct {
	b    strings.Builder
	tilt int
	p2   int
}

func (a *art) curve(base, amp, ph, fr1, fr2 int) []int {
	ys := make([]int, npts)
	amp3 := amp / 3
	for i := 0; i < npts; i++ {
		x := i * step
		y := base + a.tilt*(x-500)/1000
		y += amp * isin(fr1*x*256/2000+ph) / 1024
		y += amp3 * isin(fr2*x*256/2000+a.p2) / 1024
		ys[i] = y
	}
	return ys
}

func wInt(b *strings.Builder, n int) { b.WriteString(strconv.Itoa(n)) }

func wPt(b *strings.Builder, x, y int) {
	b.WriteString(strconv.Itoa(x))
	b.WriteString(" ")
	b.WriteString(strconv.Itoa(y))
}

// wRel writes the relative pairs "dx dy dx dy..." that follow an `l`
// between consecutive ys; a negative dy needs no separator.
func wRel(b *strings.Builder, ys []int, dx string) {
	for i := 1; i < len(ys); i++ {
		if i > 1 {
			b.WriteString(" ")
		}
		b.WriteString(dx)
		d := ys[i] - ys[i-1]
		if d >= 0 {
			b.WriteString(" ")
		}
		b.WriteString(strconv.Itoa(d))
	}
}

// wPts writes a full curve from x = 0: the absolute first point, then
// relative 25 px steps (same geometry as absolute points, ~20% fewer bytes).
func wPts(b *strings.Builder, ys []int) {
	b.WriteString("0 ")
	b.WriteString(strconv.Itoa(ys[0]))
	b.WriteString("l")
	wRel(b, ys, "25")
}

// wRibbon writes the closed shape from a curve down past the canvas.
func wRibbon(b *strings.Builder, ys []int) {
	b.WriteString("M-400 2400L-400 ")
	wInt(b, ys[0])
	b.WriteString("L")
	wPts(b, ys)
	b.WriteString("L1400 ")
	wInt(b, ys[len(ys)-1])
	b.WriteString("L1400 2400Z")
}

// SVG renders a seed under default params.
func SVG(seed string) string { return render(seed, params{-1, -1, -1, -1}) }

// SVGWith renders a seed under params; it panics on params ValidateParams
// rejects.
func SVGWith(seed, ps string) string { return render(seed, mustParams(ps)) }

func render(seed string, p params) string {
	d := derive(seed, p)
	r := newRNG(seed + "|art")
	cols, dark := eraCols[d.era], eraDark[d.era]
	eraName := eras[d.era].name
	section := sections[d.section].name

	nb := r.rr(beddings[d.bedding].lo, beddings[d.bedding].hi)
	amp := r.rr(foldings[d.folding].lo, foldings[d.folding].hi)
	f1 := r.rr(2, 5)
	f2 := r.rr(6, 14)
	p1 := r.n(256)
	p2 := r.n(256)
	tilt := r.rr(-160, 160)
	a := &art{tilt: tilt, p2: p2}
	top := -260
	if section == "Outcrop" {
		top = 230
	}
	span := 1300 - top

	// bed colours walk the palette with occasional repeats (cyclothems)
	seqc := make([]string, nb+1)
	for k := 0; k <= nb; k++ {
		m := r.rr(1, 3)
		seqc[k] = cols[(k*m+r.n(2))%len(cols)]
	}
	patt := make([]int, nb+1) // 0,1 plain; 2 sandstone, 3 shale, 4 conglomerate
	for k := 0; k <= nb; k++ {
		patt[k] = r.n(5)
	}
	thick := make([]int, nb)
	tsum := 0
	for k := 0; k < nb; k++ {
		thick[k] = r.rr(4, 14)
		tsum += thick[k]
	}
	beds := make([][]int, nb)
	acc := 0
	for k := 0; k < nb; k++ {
		base := top + span*acc/tsum
		if k == 0 {
			base -= 300
		}
		acc += thick[k]
		ak := amp + amp*k/(nb*2) // deeper beds fold more
		beds[k] = a.curve(base, ak, p1+k*r.rr(0, 3), f1, f2)
	}

	b := &a.b
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1000" width="1000" height="1000"><defs>`)
	b.WriteString(`<pattern id="s" width="12" height="12" patternUnits="userSpaceOnUse"><circle cx="3" cy="3" r="1.4" fill="#000" opacity=".22"/>` +
		`<circle cx="9" cy="8" r="1" fill="#fff" opacity=".25"/></pattern>`)
	b.WriteString(`<pattern id="h" width="40" height="7" patternUnits="userSpaceOnUse"><path d="M0 3.5H28" stroke="#000" stroke-width="1.2" opacity=".2"/></pattern>`)
	b.WriteString(`<pattern id="c" width="34" height="30" patternUnits="userSpaceOnUse"><ellipse cx="9" cy="9" rx="7" ry="5" fill="#fff" opacity=".22"/>` +
		`<ellipse cx="25" cy="22" rx="5" ry="4" fill="#000" opacity=".18"/></pattern>`)

	// g: the block drawing (beds, unconformity, intrusions, fossil), shown
	// once per fault block through <use>.
	g := &strings.Builder{}
	for k := 0; k < nb; k++ {
		col := seqc[k]
		g.WriteString(`<g fill="`)
		g.WriteString(col)
		g.WriteString(`"><path id="r`)
		wInt(g, k)
		g.WriteString(`" d="`)
		wRibbon(g, beds[k])
		g.WriteString(`" stroke="`)
		g.WriteString(shade(col, -45))
		g.WriteString(`" stroke-width="2"/></g>`)
		if patt[k] >= 2 {
			g.WriteString(`<use href="#r`)
			wInt(g, k)
			g.WriteString(`" fill="url(#`)
			g.WriteString("shc"[patt[k]-2 : patt[k]-1])
			g.WriteString(`)"/>`)
		}
	}
	if unconfs[d.unconf].name == "Angular" {
		ey := top + span*r.rr(28, 42)/100
		ea := r.rr(8, 20)
		eph := r.n(256)
		er := a.curve(ey, ea, eph, 1, 3)
		b.WriteString(`<clipPath id="u"><path d="`)
		wRibbon(b, er)
		b.WriteString(`"/></clipPath>`)
		ng := r.rr(3, 6)
		ng2 := &strings.Builder{}
		for k := 0; k < ng; k++ {
			fy := top - 300
			if k > 0 {
				fy = top + (ey-top)*k/ng
			}
			fc := make([]int, 11)
			for i := 0; i < 11; i++ {
				fc[i] = fy + tilt*(i*100-500)/4000
			}
			ng2.WriteString(`<path d="M-400 2400L-400 `)
			wInt(ng2, fc[0])
			ng2.WriteString("L")
			for i, y := range fc {
				if i > 0 {
					ng2.WriteString("L")
				}
				wPt(ng2, i*100, y)
			}
			ng2.WriteString("L1400 ")
			wInt(ng2, fc[10])
			ng2.WriteString(`L1400 2400Z" fill="`)
			ng2.WriteString(cols[(k*2+1)%len(cols)])
			ng2.WriteString(`"/>`)
		}
		ng2.WriteString(`<g clip-path="url(#u)">`)
		ng2.WriteString(g.String())
		ng2.WriteString(`</g><path d="M`)
		wPts(ng2, er)
		ng2.WriteString(`" fill="none" stroke="`)
		ng2.WriteString(dark)
		ng2.WriteString(`" stroke-width="3" opacity=".6"/>`)
		g = ng2
	}

	// intrusions belong to the block before faulting
	intr := intrusions[d.intrusion].name
	if intr == "Sill" || intr == "Dike & Sill" {
		k := r.rr(2, nb-2)
		c := beds[k]
		th := r.rr(18, 40)
		g.WriteString(`<path d="M`)
		wPts(g, c)
		g.WriteString("L1000 ")
		wInt(g, c[npts-1]+th)
		g.WriteString("l")
		back := make([]int, npts)
		for i := range back {
			back[i] = c[npts-1-i]
		}
		wRel(g, back, "-25")
		g.WriteString(`Z" fill="`)
		g.WriteString(dark)
		g.WriteString(`"/>`)
	}
	if intr == "Dike" || intr == "Dike & Sill" {
		x0 := r.rr(150, 850)
		dx := r.rr(-200, 200)
		w := r.rr(24, 60)
		g.WriteString(`<path d="M`)
		wInt(g, x0)
		g.WriteString(` -400L`)
		wInt(g, x0+w)
		g.WriteString(` -400L`)
		wInt(g, x0+w+dx)
		g.WriteString(` 1400L`)
		wInt(g, x0+dx)
		g.WriteString(` 1400Z" fill="`)
		g.WriteString(dark)
		g.WriteString(`"/>`)
	}
	if intr == "Vein Swarm" {
		g.WriteString(`<path d="`)
		nv := r.rr(10, 18)
		for v := 0; v < nv; v++ {
			x := r.rr(0, canvas)
			y := r.rr(0, canvas)
			g.WriteString("M")
			wPt(g, x, y)
			g.WriteString("l")
			wPt(g, r.rr(-60, 60), r.rr(-200, 200))
			g.WriteString("l")
			wPt(g, r.rr(-40, 40), r.rr(-120, 120))
		}
		g.WriteString(`" fill="none" stroke="`)
		if eraName == "Lapis Vein" {
			g.WriteString(cols[5])
		} else {
			g.WriteString("#f4efe4")
		}
		g.WriteString(`" stroke-width="3" opacity=".85"/>`)
	}
	if fossils[d.fossil].name == "Ammonite" {
		k := r.rr(2, nb-1)
		c := beds[k]
		i := r.rr(6, npts-7)
		fx := i * step
		fy := c[i] + r.rr(30, 60)
		path := &strings.Builder{}
		ribs := &strings.Builder{}
		path.WriteString("M")
		wPt(path, fx, fy)
		rad, ang := 2, 0
		for rad < 46 {
			ang += 12
			rad++
			px := fx + icos(ang)*rad/1024
			py := fy + isin(ang)*rad/1024
			path.WriteString("L")
			wPt(path, px, py)
			if ang%24 == 0 && rad > 12 {
				ribs.WriteString("M")
				wPt(ribs, px, py)
				ribs.WriteString("L")
				wPt(ribs, fx+icos(ang)*(rad-9)/1024, fy+isin(ang)*(rad-9)/1024)
			}
		}
		g.WriteString(`<circle cx="`)
		wInt(g, fx)
		g.WriteString(`" cy="`)
		wInt(g, fy)
		g.WriteString(`" r="`)
		wInt(g, rad)
		g.WriteString(`" fill="`)
		g.WriteString(cols[3])
		g.WriteString(`" opacity=".9"/><path d="`)
		g.WriteString(path.String())
		g.WriteString(ribs.String())
		g.WriteString(`" fill="none" stroke="`)
		g.WriteString(dark)
		g.WriteString(`" stroke-width="2.5"/>`)
	}
	b.WriteString(`<g id="b">`)
	b.WriteString(g.String())
	b.WriteString(`</g>`)

	// fault blocks: polygons between fault lines, each with its own throw
	nf := faultsT[d.faults].lo
	div := nf
	if div < 1 {
		div = 1
	}
	fxs := make([]int, nf)
	fds := make([]int, nf)
	for k := 0; k < nf; k++ {
		fxs[k] = r.rr(120+760*k/div, 120+760*(k+1)/div)
		fds[k] = r.rr(-180, 180)
	}
	// sort by (x, throw), as the prototype's sorted() of tuples
	for i := 1; i < nf; i++ {
		for j := i; j > 0 && (fxs[j] < fxs[j-1] || (fxs[j] == fxs[j-1] && fds[j] < fds[j-1])); j-- {
			fxs[j], fxs[j-1] = fxs[j-1], fxs[j]
			fds[j], fds[j-1] = fds[j-1], fds[j]
		}
	}
	throws := make([]int, nf+1)
	px0, px1 := -10, -10 // previous fault line: top x, bottom x
	throw := 0
	for k := 0; k <= nf; k++ {
		cx0, cx1 := canvas+10, canvas+10
		if k < nf {
			cx0, cx1 = fxs[k]+fds[k], fxs[k]-fds[k]
		}
		b.WriteString(`<clipPath id="f`)
		wInt(b, k)
		b.WriteString(`"><path d="M`)
		wPt(b, px0, -10)
		b.WriteString("L")
		wPt(b, cx0, -10)
		b.WriteString("L")
		wPt(b, cx1, canvas+10)
		b.WriteString("L")
		wPt(b, px1, canvas+10)
		b.WriteString(`Z"/></clipPath>`)
		throws[k] = throw
		px0, px1 = cx0, cx1
		m := r.rr(30, 140)
		if r.n(2) != 0 {
			throw += m
		} else {
			throw -= m
		}
	}
	if section == "Cores" {
		b.WriteString(`<clipPath id="k">`)
		writeCoreRects(b)
		b.WriteString(`</clipPath>`)
	}
	var surf []int
	if section == "Outcrop" {
		sa := r.rr(30, 60)
		sph := r.n(256)
		surf = a.curve(top+20, sa, sph, 1, 2)
		b.WriteString(`<clipPath id="o"><path d="`)
		wRibbon(b, surf)
		b.WriteString(`"/></clipPath>`)
	}
	b.WriteString(`</defs>`)
	switch section {
	case "Cores":
		b.WriteString(`<rect width="1000" height="1000" fill="#ece6da"/><path d="`)
		for k := 0; k < 4; k++ {
			for y := 150; y < 880; y += 25 {
				b.WriteString("M")
				wPt(b, 80+200*k, y)
				if y%100 == 0 {
					b.WriteString("h14")
				} else {
					b.WriteString("h7")
				}
			}
		}
		b.WriteString(`" stroke="#6a6258" stroke-width="2"/><g clip-path="url(#k)">`)
	case "Outcrop":
		sky := "#e9e1cf"
		if eraName == "Basalt Coast" {
			sky = "#c9d3d8"
		} else if eraName == "Lapis Vein" {
			sky = "#d9dde6"
		}
		b.WriteString(`<rect width="1000" height="1000" fill="`)
		b.WriteString(sky)
		b.WriteString(`"/><circle cx="`)
		wInt(b, r.rr(150, 850))
		b.WriteString(`" cy="`)
		wInt(b, r.rr(70, 150))
		b.WriteString(`" r="`)
		wInt(b, r.rr(34, 60))
		b.WriteString(`" fill="#f4efe2"/><g clip-path="url(#o)">`)
	default:
		b.WriteString(`<g>`)
	}
	for k := 0; k <= nf; k++ {
		b.WriteString(`<g clip-path="url(#f`)
		wInt(b, k)
		b.WriteString(`)"><use href="#b" y="`)
		wInt(b, throws[k])
		b.WriteString(`"/></g>`)
	}
	for k := 0; k < nf; k++ {
		b.WriteString(`<path d="M`)
		wPt(b, fxs[k]+fds[k], -10)
		b.WriteString("L")
		wPt(b, fxs[k]-fds[k], canvas+10)
		b.WriteString(`" stroke="`)
		b.WriteString(dark)
		b.WriteString(`" stroke-width="4" opacity=".75"/>`)
	}
	b.WriteString(`</g>`)
	if section == "Outcrop" {
		b.WriteString(`<path d="M`)
		wPts(b, surf)
		b.WriteString(`" fill="none" stroke="#4a5a3a" stroke-width="7" stroke-linecap="round"/>`)
	}
	if section == "Cores" {
		b.WriteString(`<g fill="none" stroke="#3a342c" stroke-width="3">`)
		writeCoreRects(b)
		b.WriteString(`</g>`)
	}
	b.WriteString(`</svg>`)
	return b.String()
}

func writeCoreRects(b *strings.Builder) {
	for k := 0; k < 4; k++ {
		b.WriteString(`<rect x="`)
		wInt(b, 110+200*k)
		b.WriteString(`" y="`)
		wInt(b, 120+30*(k%2))
		b.WriteString(`" width="150" height="760" rx="75"/>`)
	}
}

// Package strata is the thin adapter that registers the Strata engine
// (p/…/sinopia/art/strata/v1) with core: cross-sections of an invented
// earth, with an optional params form (era, section, bedding, folding).
//
// The adapter is stateless and has no admin: what it renders is fixed by
// the p/ package it imports, which can never change. Never mark this realm
// private (design §5.4: a re-deployable adapter could swap the art).
package strata

import (
	art "gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/art/strata/v1"
	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
	"gno.land/r/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia3/core"
)

// author is the address that claims the engine in core (ClaimEngine).
// TODO(mainnet): the platform's engine-author key, not the deployer.
var author = address("g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06")

func Author() address { return author }

// AuthorFeeBps is the author's fee on sales of collections by other
// creators (engine.Manifest.FeeBps; 0 for the author's own collections).
// TODO(mainnet): product decision; 1% here so Onyx exercises the path.
const AuthorFeeBps = 100

// impl is zero-size and declared here, so core runs it with this realm's
// authority (interrealm v2 borrow rule #1).
type impl struct{}

func (impl) Manifest() engine.Manifest {
	m := art.Manifest()
	m.Author = author
	m.FeeBps = AuthorFeeBps
	return m
}

func (impl) ValidateParams(params string) error { return art.ValidateParams(params) }

func (impl) Traits(in engine.Input) []engine.Trait { return art.Traits(in) }

func (impl) Render(in engine.Input) string { return art.Render(in) }

// Register is an explicit call, not init: under the inert package policy
// init runs inside the approver's transaction (RA B-1). Anyone may call it;
// it can only ever register this realm, once.
func Register(cur realm) string {
	return core.RegisterEngine(cross(cur), impl{})
}

// RenderSeed and TraitsSeed are the plan-B surface (design §5.6): if
// dynamic registration fails on chain, readers call the engine directly.
func RenderSeed(seed, params string) string {
	if err := art.ValidateParams(params); err != nil {
		panic(err)
	}
	return art.SVGWith(seed, params)
}

func TraitsSeed(seed, params string) []engine.Trait {
	in := engine.SampleInput()
	in.Seed, in.Params = seed, params
	if err := art.ValidateParams(params); err != nil {
		panic(err)
	}
	return art.Traits(in)
}

// Package rubrica is an asemic-script engine: every token invents an
// alphabet of nine to sixteen glyphs (strokes on a 3x4 node grid) and writes
// one page with it — a ruled manuscript, an inscribed stele, a scroll or a
// glossed page — with red rubrics (initials, first lines) marking where a
// reader should begin.
//
// It is a stateless p/ package implementing engine/v1. Pure integer maths
// (FNV-1a + splitmix64 stream, truncating division, a 256-step cosine
// table), so the TypeScript twin (frontend/src/engines/rubrica.ts) renders
// the same bytes. Traits come from their own cheap stream (seed+"|traits")
// and never render; the art uses seed+"|art", so art draws never shift traits.
//
// Glyphs are defined once in <defs> and placed with <use>; each line is one
// translate and each glyph only an x. A hard glyph budget keeps every page
// small (see GlyphBudget).
package rubrica

import (
	"errors"
	"strconv"
	"strings"

	"gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/sinopia/engine/v1"
)

// TraitTypes in the order Traits returns them.
var traitTypes = []string{"Script", "Layout", "Hand", "Rubrication", "Vellum", "Ink", "Damage", "Alphabet", "Rarity"}

// MaxSVGBytes: measured max is ~19.5 KB over thousands of seeds and every
// forced layout; the glyph budget bounds the worst case well below this.
const MaxSVGBytes = 28672

// GlyphBudget and GlossBudget cap the glyphs placed on one page: the size
// (and gas) knob of the engine. A full Fine-hand page holds ~520 glyphs; the
// glossed page's small gloss would hold ~700, so it gets a tighter cap that is
// shared out evenly over its five blocks.
const (
	GlyphBudget = 560
	GlossBudget = 440
)

// ParamsSchema is the Studio form: three optional overrides and a damage
// switch. Studio sends JSON.stringify of the values in this order.
const ParamsSchema = `{"type":"object","properties":{` +
	`"script":{"type":"string","title":"Script","enum":["Any","Uncial","Lapidary","Cursive","Runic","Hanging"],"default":"Any"},` +
	`"layout":{"type":"string","title":"Layout","enum":["Any","Single Column","Two Columns","Stele","Scroll","Glossed"],"default":"Any"},` +
	`"vellum":{"type":"string","title":"Vellum","enum":["Any","Calfskin","Goatskin","Rag Paper","Purple"],"default":"Any"},` +
	`"damage":{"type":"boolean","title":"Damage","default":true}}}`

// Manifest describes the engine. Author and FeeBps are set by the adapter.
func Manifest() engine.Manifest {
	return engine.Manifest{
		Name:    "Rubrica",
		Version: "1.0.0",
		Description: "Every Rubrica invents an alphabet of nine to sixteen letters and writes one page in it, " +
			"a manuscript, a stele, a scroll or a glossed text, with red ink marking where a reader should begin.",
		License:      "TBD",
		ParamsSchema: ParamsSchema,
		TraitTypes:   append([]string{}, traitTypes...),
		Living:       false,
		MaxSVGBytes:  MaxSVGBytes,
	}
}

// ---------------------------------------------------------------------------
// Params: "" (the showcase look) or exactly the canonical Studio JSON
// {"script":"…","layout":"…","vellum":"…","damage":true|false}.
// ---------------------------------------------------------------------------

// Params are the decoded collection params. "Any" keeps the seeded draw.
type Params struct {
	Script, Layout, Vellum string
	Damage                 bool
}

var (
	scriptParam = []string{"Any", "Uncial", "Lapidary", "Cursive", "Runic", "Hanging"}
	layoutParam = []string{"Any", "Single Column", "Two Columns", "Stele", "Scroll", "Glossed"}
	vellumParam = []string{"Any", "Calfskin", "Goatskin", "Rag Paper", "Purple"}
	errParams   = errors.New("rubrica: params must be \"\" or the canonical JSON")
)

// DefaultParams is what "" means.
func DefaultParams() Params { return Params{"Any", "Any", "Any", true} }

// ParseParams decodes "" or the canonical JSON and refuses anything else
// (other key order, spaces, unknown keys or values, "{}").
func ParseParams(s string) (Params, error) {
	if s == "" {
		return DefaultParams(), nil
	}
	var p Params
	rest := s
	lit := func(l string) bool {
		if !strings.HasPrefix(rest, l) {
			return false
		}
		rest = rest[len(l):]
		return true
	}
	str := func(allowed []string) (string, bool) {
		end := strings.IndexByte(rest, '"')
		if end < 0 {
			return "", false
		}
		v := rest[:end]
		rest = rest[end:]
		for _, a := range allowed {
			if a == v {
				return v, true
			}
		}
		return "", false
	}
	ok := false
	if !lit(`{"script":"`) {
		return p, errParams
	}
	if p.Script, ok = str(scriptParam); !ok {
		return p, errors.New("rubrica: invalid script")
	}
	if !lit(`","layout":"`) {
		return p, errParams
	}
	if p.Layout, ok = str(layoutParam); !ok {
		return p, errors.New("rubrica: invalid layout")
	}
	if !lit(`","vellum":"`) {
		return p, errParams
	}
	if p.Vellum, ok = str(vellumParam); !ok {
		return p, errors.New("rubrica: invalid vellum")
	}
	if !lit(`","damage":`) {
		return p, errParams
	}
	switch rest {
	case "true}":
		p.Damage = true
	case "false}":
		p.Damage = false
	default:
		return p, errParams
	}
	return p, nil
}

// ValidateParams accepts "" and the canonical JSON only.
func ValidateParams(params string) error {
	_, err := ParseParams(params)
	return err
}

func mustParams(s string) Params {
	p, err := ParseParams(s)
	if err != nil {
		panic(err)
	}
	return p
}

// Traits returns the nine traits of in.Seed under in.Params, in TraitTypes
// order. It never renders.
func Traits(in engine.Input) []engine.Trait {
	t := TraitsOf(in.Seed, in.Params)
	return []engine.Trait{
		{Type: "Script", Value: t.Script},
		{Type: "Layout", Value: t.Layout},
		{Type: "Hand", Value: t.Hand},
		{Type: "Rubrication", Value: t.Rubrication},
		{Type: "Vellum", Value: t.Vellum},
		{Type: "Ink", Value: t.Ink},
		{Type: "Damage", Value: t.Damage},
		{Type: "Alphabet", Value: strconv.Itoa(t.Alphabet)},
		{Type: "Rarity", Value: t.Rarity},
	}
}

// Render returns the raw SVG for in.Seed under in.Params.
func Render(in engine.Input) string { return SVG(in.Seed, in.Params) }

// ---------------------------------------------------------------------------
// Deterministic randomness: FNV-1a over the seed, then splitmix64 (Genesis).
// ---------------------------------------------------------------------------

const (
	fnvOffset uint64 = 14695981039346656037
	fnvPrime  uint64 = 1099511628211
)

type rng struct{ s uint64 }

func newRNG(seed string) *rng {
	h := fnvOffset
	for i := 0; i < len(seed); i++ {
		h ^= uint64(seed[i])
		h *= fnvPrime
	}
	if h == 0 {
		h = fnvPrime
	}
	return &rng{s: h}
}

func (r *rng) next() uint64 {
	r.s += 0x9E3779B97F4A7C15
	z := r.s
	z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9
	z = (z ^ (z >> 27)) * 0x94D049BB133111EB
	return z ^ (z >> 31)
}

// n returns a value in [0, k).
func (r *rng) n(k int) int {
	if k <= 0 {
		return 0
	}
	return int(r.next() % uint64(k))
}

// rr returns a value in [a, b].
func (r *rng) rr(a, b int) int { return a + r.n(b-a+1) }

// ---------------------------------------------------------------------------
// Trait tables. Weights read as percent; score feeds the rarity tier.
// ---------------------------------------------------------------------------

type option struct {
	name   string
	weight int
	score  int
	v      int // Hand: glyph height
}

func pick(r *rng, table []option) option {
	total := 0
	for _, o := range table {
		total += o.weight
	}
	roll := r.n(total)
	acc := 0
	for _, o := range table {
		acc += o.weight
		if roll < acc {
			return o
		}
	}
	return table[len(table)-1]
}

func byName(table []option, name string) option {
	for _, o := range table {
		if o.name == name {
			return o
		}
	}
	return table[0]
}

var (
	scripts  = []option{{"Uncial", 26, 0, 0}, {"Lapidary", 22, 0, 0}, {"Cursive", 22, 0, 0}, {"Runic", 18, 1, 0}, {"Hanging", 12, 2, 0}}
	layouts  = []option{{"Single Column", 30, 0, 0}, {"Two Columns", 26, 0, 0}, {"Stele", 16, 1, 0}, {"Scroll", 16, 1, 0}, {"Glossed", 12, 2, 0}}
	hands    = []option{{"Fine", 30, 0, 22}, {"Book", 45, 0, 30}, {"Display", 25, 0, 40}}
	rubrics  = []option{{"None", 18, 0, 0}, {"Initials", 32, 0, 0}, {"Rubrics", 28, 0, 0}, {"Full", 22, 1, 0}}
	vellums  = []option{{"Calfskin", 40, 0, 0}, {"Goatskin", 30, 0, 0}, {"Rag Paper", 24, 0, 0}, {"Purple", 6, 4, 0}}
	inks     = []option{{"Iron Gall", 40, 0, 0}, {"Carbon", 30, 0, 0}, {"Sepia", 22, 0, 0}, {"Lapis", 8, 2, 0}}
	damages  = []option{{"None", 62, 0, 0}, {"Wormholes", 16, 1, 0}, {"Water Stain", 14, 1, 0}, {"Torn Corner", 8, 2, 0}}
	rulings  = []option{{"None", 30, 0, 0}, {"Dry-point", 45, 0, 0}, {"Pricked", 25, 0, 0}}
)

// Rarity tier cut-offs on the score (10,000-seed simulation, default
// params): Common 43% / Uncommon 26% / Rare 23% / Legendary 6% / Mythic 1.4%.
const (
	scoreMythic    = 7
	scoreLegendary = 5
	scoreRare      = 3
	scoreUncommon  = 2
)

// TraitSet is the decoded token. The SVG and the trait list both read it.
type TraitSet struct {
	Script, Layout, Hand, Rubrication string
	Vellum, Ink, Damage               string // as shown (Stone, Incised, Chrysography)
	Alphabet                          int
	Score                             int
	Rarity                            string

	ruling    string
	glyphH    int
	vellumRaw string // colour sources
	inkRaw    string
}

func derive(seed string, p Params) TraitSet {
	r := newRNG(seed + "|traits")
	// Draw order is part of the contract: every draw happens whatever the params.
	script := pick(r, scripts)
	layout := pick(r, layouts)
	hand := pick(r, hands)
	rub := pick(r, rubrics)
	vellum := pick(r, vellums)
	ink := pick(r, inks)
	damage := pick(r, damages)
	ruling := pick(r, rulings)
	alphabet := 9 + r.n(8)

	if p.Script != "Any" {
		script = byName(scripts, p.Script)
	}
	if p.Layout != "Any" {
		layout = byName(layouts, p.Layout)
	}
	if p.Vellum != "Any" {
		vellum = byName(vellums, p.Vellum)
	}
	if !p.Damage {
		damage = damages[0]
	}

	// What the page can actually show.
	if layout.name == "Stele" {
		if rub.name == "Initials" {
			rub = rubrics[0]
		}
		if rub.name == "Full" {
			rub = rubrics[2]
		}
	}
	if (layout.name == "Stele" || layout.name == "Scroll") && damage.name == "Torn Corner" {
		damage = damages[0]
	}
	t := TraitSet{
		Script: script.name, Layout: layout.name, Hand: hand.name, Rubrication: rub.name,
		Vellum: vellum.name, Ink: ink.name, Damage: damage.name, Alphabet: alphabet,
		ruling: ruling.name, glyphH: hand.v, vellumRaw: vellum.name, inkRaw: ink.name,
	}
	score := script.score + layout.score + rub.score + damage.score
	switch {
	case layout.name == "Stele":
		t.Vellum, t.Ink = "Stone", "Incised"
	case vellum.name == "Purple":
		t.Ink = "Chrysography"
		score += vellum.score
	default:
		score += ink.score
	}
	if alphabet == 16 {
		score++
	}
	t.Score = score
	switch {
	case score >= scoreMythic:
		t.Rarity = "Mythic"
	case score >= scoreLegendary:
		t.Rarity = "Legendary"
	case score >= scoreRare:
		t.Rarity = "Rare"
	case score >= scoreUncommon:
		t.Rarity = "Uncommon"
	default:
		t.Rarity = "Common"
	}
	return t
}

// TraitsOf returns the decoded traits for a seed and params string; it
// panics on invalid params (core validates them at CreateCollection).
func TraitsOf(seed, params string) TraitSet { return derive(seed, mustParams(params)) }

// TraitString is "Type=Value;…" in TraitTypes order (golden vectors).
func TraitString(seed, params string) string {
	ts := Traits(engine.Input{Seed: seed, Params: params})
	var b strings.Builder
	for i, t := range ts {
		if i > 0 {
			b.WriteByte(';')
		}
		b.WriteString(t.Type)
		b.WriteByte('=')
		b.WriteString(t.Value)
	}
	return b.String()
}

